<?php
declare(strict_types=1);
if(!$portalReady)return;
$bankReady=setting($db,'provincial_account_number')!=='';
$payhubReady=PayHub::enabled($db);$payhubKey=trim(setting($db,'payhub_public_key'));
$paymentHistory=new FinancialHistory($db,$ids,$_GET,'payments');$notifications=$paymentHistory->items;
$payhubReturnError='';
